algorithms.pseudocode:
function GENERATE_LINEAR_CODE(G):
  input: G = [g_0,...,g_{k-1}], each g_i in {0,1}^n
  C <- empty set
  for each a in {0,1}^k:
    w <- (0,...,0)  in {0,1}^n
    for i in 0..k-1:
      if a[i] = 1: w <- (w + g_i) mod 2
    add w to C
  return sorted(C)

function CERTIFY_SELF_ORTHOGONAL(C):  // C assumed linear
  for each codeword c in C:
    if (weight(c) mod 4) != 0:
      return false   // not doubly even => certificate fails
  return true        // doubly-even + linear => self-orthogonal (bridge theorem)

function WEIGHT_OF_SUM(wx, wy, ov):
  // wx = wt(x), wy = wt(y), ov = overlap(x,y)
  return wx + wy - 2*ov   // = wt(x+y) by inclusion-exclusion
